<div class="table-responsive slaughter-table-wrap"><table class="enterprise-table slaughter-table receipts-table" data-datatable="false" aria-label="Réceptions de carcasses"><thead><tr><?php foreach(['reference'=>'Référence / lot','source'=>'Ferme d’origine','date'=>'Date','weight'=>'Poids (kg)','expiry'=>'DLC','state'=>'Étape'] as$key=>$label):?><th scope="col" class="<?=$key==='weight'?'num':''?>" aria-sort="none"><button type="button" data-flow-sort="<?=e($key)?>"><?=e($label)?> <span aria-hidden="true">↕</span></button></th><?php endforeach;?><th scope="col">Actions</th></tr></thead><tbody data-flow-table-body>
<?php foreach($incoming as$t):$sentAt=$t['dispatched_at']??$t['created_at'];?>
<tr data-transfer-id="<?=e($t['id'])?>" data-flow-key="transfer-<?=e($t['id'])?>" data-flow-item data-kind="incoming" data-state="incoming" data-reference="<?=e($t['transfer_number'])?>" data-source="<?=e($t['source_name'])?>" data-date="<?=e($sentAt)?>" data-weight="<?=e($t['quantity_kg'])?>" data-expiry="<?=e($t['expiry_date'])?>" data-search="<?=e($t['source_name'].' '.$t['batch_number'].' '.$t['transfer_number'].' '.$t['conversion_number'].' '.$t['truck_plate'].' '.$t['driver_name'])?>">
<td data-label="Référence / lot"><strong><?=e($t['transfer_number'])?></strong><small><?=e($t['batch_number'])?></small></td><td data-label="Ferme d’origine"><?=e($t['source_name'])?></td><td data-label="Date"><?=e(date('d/m/Y H:i',strtotime($sentAt)))?><small class="shipment-weight-note">Expédition</small></td><td class="num" data-label="Poids (kg)"><?=$kg($t['quantity_kg'])?></td><td data-label="DLC"><?=e(date('d/m/Y',strtotime($t['expiry_date'])))?></td><td data-label="Étape"><span class="ui-status ui-status--warning">À réceptionner</span></td><td data-label="Actions"><details class="slaughter-row-actions"><summary>Détails et actions</summary><p>Abattage <?=e($t['conversion_number'])?></p><p><?=e($t['truck_plate'])?> · <?=e($t['driver_name'])?></p><?php if($canOperate&&Auth::can('butchery','create',$site)):$inlineForm=true;$action='butchery/flow/arrivals';$confirm='Enregistrer l’arrivée de cet envoi pour contrôle sanitaire ?';require __DIR__.'/form_start.php';?><input type="hidden" name="transfer_id" value="<?=e($t['id'])?>"><?php $submitLabel='Enregistrer l’arrivée';require __DIR__.'/form_end.php';unset($inlineForm);else:?><p>En attente d’un utilisateur autorisé à enregistrer l’arrivée.</p><?php endif;?></details></td></tr>
<?php endforeach;?>
<?php foreach($pending as$t):?>
<tr data-receipt-id="<?=e($t['id'])?>" data-flow-key="receipt-<?=e($t['id'])?>" data-flow-item data-kind="pending" data-state="pending" data-reference="<?=e($t['receipt_number'])?>" data-source="<?=e($t['source_name'])?>" data-date="<?=e($t['received_at'])?>" data-weight="<?=e($t['quantity_kg'])?>" data-expiry="<?=e($t['expiry_date'])?>" data-search="<?=e($t['receipt_number'].' '.$t['source_name'].' '.$t['batch_number'].' '.$t['transfer_number'])?>">
<td data-label="Référence / lot"><strong><?=e($t['receipt_number'])?></strong><small><?=e($t['batch_number'])?></small></td><td data-label="Ferme d’origine"><?=e($t['source_name'])?></td><td data-label="Date"><?=e(date('d/m/Y H:i',strtotime($t['received_at'])))?><small class="shipment-weight-note">Arrivée enregistrée</small></td><td class="num" data-label="Poids (kg)"><?=$kg($t['quantity_kg'])?></td><td data-label="DLC"><?=e(date('d/m/Y',strtotime($t['expiry_date'])))?></td><td data-label="Étape"><span class="ui-status ui-status--warning">Contrôle à effectuer</span></td><td data-label="Actions"><details class="slaughter-row-actions"><summary>Détails et actions</summary><p>Envoi <?=e($t['transfer_number'])?></p><p>Contrôlez les carcasses avant leur entrée en chambre froide.</p><?php if($canOperate&&Auth::can('butchery','validate',$site)):?><button class="btn-primary" type="button" data-workspace-modal-open="flow-receive-<?=e($t['id'])?>"><i class="bi bi-clipboard-check" aria-hidden="true"></i> Effectuer le contrôle</button><?php else:?><p>En attente d’un utilisateur autorisé à valider le contrôle.</p><?php endif;?></details></td></tr>
<?php endforeach;?></tbody></table></div>
<div class="campaign-pagination slaughter-pagination"><span data-flow-page-info role="status"></span><div><button type="button" class="btn-secondary" data-flow-page="-1">Précédent</button><span data-flow-page-label></span><button type="button" class="btn-secondary" data-flow-page="1">Suivant</button></div></div>
<?php if(!$incoming&&!$pending):?><p class="flow-empty">Aucune réception à traiter. Les carcasses apparaîtront après leur expédition depuis la ferme.</p><?php endif;?>
